package com.worksphere.controller; import com.worksphere.dto.dispute.*; import com.worksphere.service.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/admin") public class AdminController {private final AdminService admin;private final DisputeService disputes;public AdminController(AdminService a,DisputeService d){admin=a;disputes=d;} @GetMapping("/dashboard") public Object dashboard(){return admin.dashboard();} @GetMapping("/users") public Object users(){return admin.users();} @GetMapping("/jobs") public Object jobs(){return admin.jobs();} @GetMapping("/applications") public Object applications(){return admin.applications();} @GetMapping("/commitments") public Object commitments(){return admin.commitments();} @GetMapping("/ratings") public Object ratings(){return admin.ratings();} @GetMapping("/strikes") public Object strikes(){return admin.strikes();} @GetMapping("/disputes") public Object disputes(){return disputes.all();} @PutMapping("/disputes/{id}/resolve") public Object resolve(@PathVariable Long id,@RequestBody DisputeResolutionRequest r){return disputes.resolve(id,r);} }
